/// <summary>
///     The <c>AVAKBVSalesVolumeTableType</c> class is the execution class for <c>BPs</c>
/// </summary>
class AVAKBVSalesVolumeTableType
{
    NDX_KBVSalesVolumeTable     nDX_KBVSalesVolumeTable;
    NDX_KBVSalesVolumeLine      nDX_KBVSalesVolumeLine;
    Map                         nDXMapProductGroup;
    container                   conRecLine;

}

Method.Source:
/// <summary>
///    AVA <c>createNDX_KBVSalesVolumeLine</c> method.
/// </summary>
/// <param name="_salesQuotationTable">
///    <c>SalesQuotationTable</c> as type
/// </param>
/// <param name="_amountMST">
///    <c>AmountMST</c> as type
/// </param>
/// <returns>
///    <c>NDX_KBVSalesVolumeLine</c> as return value
/// </returns>
public NDX_KBVSalesVolumeLine createNDX_KBVSalesVolumeLine(SalesQuotationTable _salesQuotationTable, AmountMST _amountMST = 0)
{
    nDX_KBVSalesVolumeLine = NDX_KBVSalesVolumeLine::findOrCreate(  nDX_KBVSalesVolumeTable.RecId,
                                                                    _salesQuotationTable.KCS_KBVProductGroupID,
                                                                    _salesQuotationTable.dataAreaId,
                                                                    false   );
    nDX_KBVSalesVolumeLine.SalesQuotationTable      = _salesQuotationTable.RecId;
    nDX_KBVSalesVolumeLine.AmountMST                = _amountMST;

    return nDX_KBVSalesVolumeLine;
}

/// <summary>
///    AVA <c>initialize</c> method.
/// </summary>
public void initialize()
{
    if (NDX_KBVSalesVolumeTable.RecId)
    {
        if (nDX_KBVSalesVolumeTable.GLB == NoYes::Yes)
        {
            while select nDX_KBVSalesVolumeLine
            where nDX_KBVSalesVolumeLine.NDX_KBVSalesVolumeTable == NDX_KBVSalesVolumeTable.RecId
            {
                conRecLine += nDX_KBVSalesVolumeLine.RecId;
            }
        }
        else
        {
            while select nDX_KBVSalesVolumeLine
            where   nDX_KBVSalesVolumeLine.NDX_KBVSalesVolumeTable == NDX_KBVSalesVolumeTable.RecId
                &&  nDX_KBVSalesVolumeLine.UK == curext()
            {
                conRecLine += nDX_KBVSalesVolumeLine.RecId;
            }
        }
    }

    nDX_KBVSalesVolumeTable.AmountMST           = 0;

    //nDXMapProductGroup = new Map(typeId2Type(extendedTypeNum(KCS_DirProductGroupID)), Types::Record);
    nDXMapProductGroup = new Map(Types::String, Types::Record);
}

/// <summary>
///    AVA <c>MapProductGroupInsert</c> method.
/// </summary>
/// <param name="_productGroupId">
///    <c>KCS_DirProductGroupID</c> as type
/// </param>
/// <param name="_nDX_KBVSalesVolumeLine">
///    <c>NDX_KBVSalesVolumeLine</c> as type
/// </param>
public void MapProductGroupInsert(KCS_DirProductGroupID _productGroupId, NDX_KBVSalesVolumeLine _nDX_KBVSalesVolumeLine)
{
    nDXMapProductGroup.insert(_productGroupId, _nDX_KBVSalesVolumeLine);
}

/// <summary>
///    AVA <c>new</c> method.
/// </summary>
protected void new()
{
    //nDXMapProductGroup  = new Map(typeId2Type(extendedTypeNum(KCS_DirProductGroupID)), Types::Record);
    nDXMapProductGroup  = new Map(Types::String, Types::Record);
    conRecLine          = connull();
}

/// <summary>
///    AVA <c>parmNDX_KBVSalesVolumeTable</c> method.
/// </summary>
/// <param name="_parmValue">
///    <c>NDX_KBVSalesVolumeTable</c> as type
/// </param>
/// <returns>
///    <c>NDX_KBVSalesVolumeTable</c> as return value
/// </returns>
public NDX_KBVSalesVolumeTable parmNDX_KBVSalesVolumeTable(NDX_KBVSalesVolumeTable _parmValue = NDX_KBVSalesVolumeTable)
{
    nDX_KBVSalesVolumeTable = _parmValue;
    return nDX_KBVSalesVolumeTable;
}

/// <summary>
///    AVA <c>save</c> method.
/// </summary>
/// <param name="_amountMst">
///    <c>AmountMST</c> as type
/// </param>
public void save(AmountMST _amountMst)
{
    MapEnumerator   mapEnumerator;
    int             pos;
    RefRecId        refRecId;

    ttsbegin;

    nDX_KBVSalesVolumeTable.AmountMST = nDX_KBVSalesVolumeTable.GLB ==  NoYes::Yes?_amountMst:0;
    nDX_KBVSalesVolumeTable.write();

    // save lines
    mapEnumerator = nDXMapProductGroup.getEnumerator();
    while (mapEnumerator.moveNext())
    {
        nDX_KBVSalesVolumeLine = mapEnumerator.currentValue();

        nDX_KBVSalesVolumeLine.selectForUpdate(true);
        nDX_KBVSalesVolumeLine.NDX_KBVSalesVolumeTable = nDX_KBVSalesVolumeTable.RecId;

        if (nDX_KBVSalesVolumeLine.RecId)
        {
            pos = confind(conRecLine, nDX_KBVSalesVolumeLine.RecId);
            if (pos)
            {
                conRecLine = condel(conRecLine, pos, 1);
            }
        }

        nDX_KBVSalesVolumeLine.write();
    }
    for (pos=1; pos <= conlen(conRecLine); ++pos)
    {
        refRecId = conpeek(conRecLine, pos);

        select forUpdate nDX_KBVSalesVolumeLine
        where nDX_KBVSalesVolumeLine.recId == refRecId;

        if (nDX_KBVSalesVolumeLine)
        {
            nDX_KBVSalesVolumeLine.delete();
        }
    }
    ttscommit;
}

/// <summary>
///    AVA <c>saveNDX_KBVSalesVolumeLine</c> method.
/// </summary>
public void saveNDX_KBVSalesVolumeLine()
{
    nDX_KBVSalesVolumeLine.write();
}

/// <summary>
///    AVA <c>checkData</c> method.
/// </summary>
/// <param name="_kCS_KBVBuildingProjectID">
///    <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
static void checkData(KCS_KBVBuildingProjectID _kCS_KBVBuildingProjectID = '')
{
    KCS_KBVBuildingProjectTable kCS_KBVBuildingProjectTable;
    Query                       q;
    QueryRun                    qr;
    QueryBuildDataSource        qbds;
    AVABPJobsUpdateSalesVolume  kCS_KBVUpdatePotSalesVol;
    container                   conBVCompanies;
    int                         counter;
    DataAreaId                  uk;
    int                         i;

    conBVCompanies = AVAKBVBuildingProjectHelper::getAllBPCompanies();

    kCS_KBVUpdatePotSalesVol = AVABPJobsUpdateSalesVolume::construct();
    kCS_KBVUpdatePotSalesVol.parmUpdateKcs_KBVPotentialSalesVolumeTbl(false);

    q = new Query();

    qbds = q.addDataSource(tablenum(KCS_KBVBuildingProjectTable));
    qbds.addOrderByField(fieldnum(KCS_KBVBuildingProjectTable, CreatedDateTime), SortOrder::Descending);
    if (_kCS_KBVBuildingProjectID)
    {
        qbds.addRange(fieldnum(KCS_KBVBuildingProjectTable, KCS_KBVBuildingProjectID)).value(QueryValue(_kCS_KBVBuildingProjectID));
    }
    qr = new QueryRun(q);
    while (qr.next())
    {
        kCS_KBVBuildingProjectTable = qr.get(tablenum(KCS_KBVBuildingProjectTable));
        for (i=1; i<=conlen(conBVCompanies); i++)
        {
            uk = conpeek(conBVCompanies, i);
            changecompany(uk)
            {
                kCS_KBVUpdatePotSalesVol.updateSalesVolumeLoc(kCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID);
            }
        }
        kCS_KBVUpdatePotSalesVol.updateSalesVolumeGLB(kCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID);
        ++counter;
        Debug::printDebug(strfmt("@NDX:NXAP1RightParenthesisSpaceP2HyphenP3",   counter,
                                                                                kCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID,
                                                                                kCS_KBVBuildingProjectTable.createdDateTime             )   );
    }
}

/// <summary>
///    AVA <c>construct</c> method.
/// </summary>
/// <param name="_nDX_KBVSalesVolumeTable">
///    <c>NDX_KBVSalesVolumeTable</c> as type
/// </param>
/// <returns>
///    <c>AVAKBVSalesVolumeTableType</c> as return value
/// </returns>
static public AVAKBVSalesVolumeTableType construct(NDX_KBVSalesVolumeTable _nDX_KBVSalesVolumeTable)
{
    AVAKBVSalesVolumeTableType    nDX_KBVSalesVolumeTableType;

    nDX_KBVSalesVolumeTableType = new AVAKBVSalesVolumeTableType();
    nDX_KBVSalesVolumeTableType.parmNDX_KBVSalesVolumeTable(_nDX_KBVSalesVolumeTable);

    return nDX_KBVSalesVolumeTableType;
}

/// <summary>
///    AVA <c>constructFromKBVBuildingProjectId</c> method.
/// </summary>
/// <param name="_kCS_KBVBuildingProjectID">
///    <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
/// <param name="_gLB">
///    <c>NoYes</c> as type
/// </param>
/// <param name="_currencyCode">
///    <c>CurrencyCode</c> as type
/// </param>
/// <returns>
///    <c>AVAKBVSalesVolumeTableType</c> as return value
/// </returns>
static public AVAKBVSalesVolumeTableType constructFromKBVBuildingProjectId( KCS_KBVBuildingProjectID    _kCS_KBVBuildingProjectID,
                                                                            NoYes                       _gLB,
                                                                            CurrencyCode                _currencyCode               )
{
    NDX_KBVSalesVolumeTable     nDX_KBVSalesVolumeTable;
    AVAKBVSalesVolumeTableType  nDX_KBVSalesVolumeTableType;

    nDX_KBVSalesVolumeTableType = new AVAKBVSalesVolumeTableType();

    nDX_KBVSalesVolumeTable     = NDX_KBVSalesVolumeTable::findOrCreate(_gLB,
                                                                        _kCS_KBVBuildingProjectID,
                                                                        false                       );
    nDX_KBVSalesVolumeTable.MasterCurrencyCode  = _currencyCode;
    nDX_KBVSalesVolumeTableType.parmNDX_KBVSalesVolumeTable(nDX_KBVSalesVolumeTable);

    return nDX_KBVSalesVolumeTableType;
}
